package com.pandinila.broadband_management.controller;import com.pandinila.broadband_management.entity.*;import com.pandinila.broadband_management.entity.Enums.RiskLevel;import com.pandinila.broadband_management.repository.ComplaintPredictionRepository;import com.pandinila.broadband_management.service.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/predictions") public class PredictionController {private final ComplaintPredictionRepository repo;private final CustomerService customers;private final MonitoringService monitoring;public PredictionController(ComplaintPredictionRepository r,CustomerService c,MonitoringService m){repo=r;customers=c;monitoring=m;}@GetMapping public List<ComplaintPrediction> all(){return repo.findTop100ByOrderByIdDesc();}@GetMapping("/customer/{customerId}") public ComplaintPrediction one(@PathVariable String customerId){Customer c=customers.all().stream().filter(x->x.getCustomerId().equals(customerId)).findFirst().orElseThrow();return monitoring.latestPrediction(c).orElseThrow();}@GetMapping("/high-risk") public List<ComplaintPrediction> high(){return customers.all().stream().map(monitoring::latestPrediction).flatMap(Optional::stream).filter(p->p.getRiskLevel()==RiskLevel.HIGH).toList();}@PostMapping("/analyze/{customerId}") public ComplaintPrediction analyze(@PathVariable Long customerId){Customer c=customers.one(customerId);return monitoring.latestMetric(c).map(monitoring::process).orElseThrow(()->new IllegalStateException("No network metrics exist for this customer"));}@PostMapping("/analyze-all") public List<ComplaintPrediction> allAnalyze(){return customers.all().stream().map(monitoring::latestMetric).flatMap(Optional::stream).map(monitoring::process).toList();}}
